    func addFriend(login: String, note: String) async throws 
    
    func agree(nickname: String, icon: UInt16) async throws 
    
    /**
     * For servers that never answer the agreement.
     */
    func agreeNowait(nickname: String, icon: UInt16) 
    
    func block(login: String) async throws 
    
    func disconnect() 
    
    func downloadMedia(id: String) async throws  -> MediaData
    
    func findUser(login: String) async throws  -> FoundUser
    
    func getBuddyIcon(login: String) async throws  -> BuddyIcon?
    
    func getInfo(login: String) async throws  -> UserInfo
    
    /**
     * The whole roster; also the signal to send the offline backlog.
     */
    func getRoster() async throws  -> [Buddy]
    
    func getUsers() async throws  -> [ChatUser]
    
    func gifIcon(userId: UInt16) async throws  -> Data?
    
    func gifIcons() async throws  -> [GifIcon]
    
    func hasBuddyIcons()  -> Bool
    
    func info()  -> ServerInfo
    
    func isOpen()  -> Bool
    
    func removeFriend(login: String) async throws 
    
    func respond(login: String, accept: Bool) async throws 
    
    func search(query: String) async throws  -> [FoundUser]
    
    func sendChat(text: String, emote: Bool) 
    
    /**
     * Chat with a picture; `text` is what clients without pictures see.
     */
    func sendChatMedia(text: String, media: MediaRef) 
    
    /**
     * Sends an IM under `guid` (from `new_guid`, so the app can show it first).
     * True when the server queued it for someone offline. A timeout is retried
     * once with the same GUID, which the server de-duplicates.
     */
    func sendIm(to: String, guid: String, body: String) async throws  -> Bool
    
    /**
     * A classic private message to someone in a room, optionally with a picture.
     */
    func sendPrivate(userId: UInt16, text: String, media: MediaRef?) async throws 
    
    /**
     * Our private name for them; empty clears it.
     */
    func setAlias(login: String, alias: String) async throws 
    
    /**
     * Uploads a Buddy Icon (empty clears it); the server's hash for what it stored.
     */
    func setBuddyIcon(picture: Data) async throws  -> String?
    
    /**
     * Sets our GIF icon; empty clears it.
     */
    func setGifIcon(gif: Data) async throws 
    
    /**
     * Replaces the whole profile.
     */
    func setInfo(profile: Profile) async throws 
    
    /**
     * `discoverable`: None leaves it as it is.
     */
    func setPresence(presence: Presence, status: String, discoverable: Bool?) async throws 
    
    func typing(to: String, typing: Bool) 
    
    func unblock(login: String) async throws 
    
    /**
     * Uploads a picture; put the handle in a chat line with `send_chat_media`.
     */
    func uploadMedia(data: Data) async throws  -> MediaRef
    
}
open class Session: SessionProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_himffi_fn_clone_session(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_himffi_fn_free_session(handle, $0) }
    }

    

    
