enum HimError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Connect(message: String
    )
    /**
     * Wrong screen name or password, or the account is disabled.
     */
    case LoginFailed(message: String
    )
    case Security(message: String
    )
    /**
     * The server said no; `reason` is its reason code, when it gave one.
     */
    case Server(message: String, reason: UInt16?
    )
    case Timeout
    case NotConnected

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension HimError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHimError: FfiConverterRustBuffer {
    typealias SwiftType = HimError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HimError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Connect(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .LoginFailed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Security(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Server(
            message: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterOptionUInt16.read(from: &buf)
            )
        case 5: return .Timeout
        case 6: return .NotConnected

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HimError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Connect(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .LoginFailed(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Security(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Server(message,reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            FfiConverterOptionUInt16.write(reason, into: &buf)
            
        
        case .Timeout:
            writeInt(&buf, Int32(5))
        
        
        case .NotConnected:
            writeInt(&buf, Int32(6))
        
        }
    }
}


