public enum HimEvent: Equatable, Hashable {
    
    /**
     * A roster entry, whole (a Removed state means it's gone).
     */
    case buddy(buddy: Buddy
    )
    case friendRequest(login: String, note: String?
    )
    case presence(update: PresenceUpdate
    )
    case message(message: IncomingMessage
    )
    case ack(guid: String, login: String, kind: AckKind
    )
    case typing(login: String, typing: Bool
    )
    /**
     * The server's agreement; accept it with `agree`.
     */
    case agreement(text: String
    )
    /**
     * Public chat; `chat_id` is set for a private chat room.
     */
    case chat(chatId: UInt32?, text: String, media: MediaRef?
    )
    case userChanged(user: ChatUser
    )
    case userLeft(id: UInt16
    )
    /**
     * A classic private message.
     */
    case privateMessage(fromId: UInt16, fromName: String, text: String, media: MediaRef?
    )
    /**
     * Someone's GIF icon changed; fetch it with `gif_icon`.
     */
    case gifIconChanged(userId: UInt16
    )
    case serverMessage(text: String
    )
    /**
     * Another of our sessions changed our Buddy Icon; None = cleared.
     */
    case ownIconChanged(hash: String?
    )
    case disconnected(reason: String
    )





}

#if compiler(>=6)
extension HimEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHimEvent: FfiConverterRustBuffer {
    typealias SwiftType = HimEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HimEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .buddy(buddy: try FfiConverterTypeBuddy.read(from: &buf)
        )
        
        case 2: return .friendRequest(login: try FfiConverterString.read(from: &buf), note: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .presence(update: try FfiConverterTypePresenceUpdate.read(from: &buf)
        )
        
        case 4: return .message(message: try FfiConverterTypeIncomingMessage.read(from: &buf)
        )
        
        case 5: return .ack(guid: try FfiConverterString.read(from: &buf), login: try FfiConverterString.read(from: &buf), kind: try FfiConverterTypeAckKind.read(from: &buf)
        )
        
        case 6: return .typing(login: try FfiConverterString.read(from: &buf), typing: try FfiConverterBool.read(from: &buf)
        )
        
        case 7: return .agreement(text: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .chat(chatId: try FfiConverterOptionUInt32.read(from: &buf), text: try FfiConverterString.read(from: &buf), media: try FfiConverterOptionTypeMediaRef.read(from: &buf)
        )
        
        case 9: return .userChanged(user: try FfiConverterTypeChatUser.read(from: &buf)
        )
        
        case 10: return .userLeft(id: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 11: return .privateMessage(fromId: try FfiConverterUInt16.read(from: &buf), fromName: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf), media: try FfiConverterOptionTypeMediaRef.read(from: &buf)
        )
        
        case 12: return .gifIconChanged(userId: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 13: return .serverMessage(text: try FfiConverterString.read(from: &buf)
        )
        
        case 14: return .ownIconChanged(hash: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 15: return .disconnected(reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HimEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .buddy(buddy):
            writeInt(&buf, Int32(1))
            FfiConverterTypeBuddy.write(buddy, into: &buf)
            
        
        case let .friendRequest(login,note):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(login, into: &buf)
            FfiConverterOptionString.write(note, into: &buf)
            
        
        case let .presence(update):
            writeInt(&buf, Int32(3))
            FfiConverterTypePresenceUpdate.write(update, into: &buf)
            
        
        case let .message(message):
            writeInt(&buf, Int32(4))
            FfiConverterTypeIncomingMessage.write(message, into: &buf)
            
        
        case let .ack(guid,login,kind):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(guid, into: &buf)
            FfiConverterString.write(login, into: &buf)
            FfiConverterTypeAckKind.write(kind, into: &buf)
            
        
        case let .typing(login,typing):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(login, into: &buf)
            FfiConverterBool.write(typing, into: &buf)
            
        
        case let .agreement(text):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .chat(chatId,text,media):
            writeInt(&buf, Int32(8))
            FfiConverterOptionUInt32.write(chatId, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterOptionTypeMediaRef.write(media, into: &buf)
            
        
        case let .userChanged(user):
            writeInt(&buf, Int32(9))
            FfiConverterTypeChatUser.write(user, into: &buf)
            
        
        case let .userLeft(id):
            writeInt(&buf, Int32(10))
            FfiConverterUInt16.write(id, into: &buf)
            
        
        case let .privateMessage(fromId,fromName,text,media):
            writeInt(&buf, Int32(11))
            FfiConverterUInt16.write(fromId, into: &buf)
            FfiConverterString.write(fromName, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterOptionTypeMediaRef.write(media, into: &buf)
            
        
        case let .gifIconChanged(userId):
            writeInt(&buf, Int32(12))
            FfiConverterUInt16.write(userId, into: &buf)
            
        
        case let .serverMessage(text):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .ownIconChanged(hash):
            writeInt(&buf, Int32(14))
            FfiConverterOptionString.write(hash, into: &buf)
            
        
        case let .disconnected(reason):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


